(function (window) {
    'use strict';

    // Funções puras de matemática e formatação extraídas de main.js

    // Logos oficiais (SOP-CE e Governo do Estado do Ceara) para o cabecalho dos
    // relatorios formais (Analise Tecnica, Analise Documental etc.). Embutidas como
    // data URI (em vez de <img src="logo-sop.png">) porque os relatorios da Curva
    // ABC/Checklist abrem em janelas proprias via window.open+document.write - assim
    // a imagem aparece sempre, sem depender da resolucao de caminho relativo dessa
    // nova janela.
    var LOGO_SOP_BASE64 = 'data:image/png;base64,';
    var LOGO_CEARA_BASE64 = 'data:image/png;base64,';

    function montarCabecalhoLogosRelatorio(titulo) {
        var html = '<div style="display:flex;align-items:center;justify-content:space-between;margin:0 0 16px 0;">'
            + '<img src="' + LOGO_SOP_BASE64 + '" alt="SOP-CE" style="height:48px;width:auto;display:block;">'
            + '<img src="' + LOGO_CEARA_BASE64 + '" alt="Governo do Estado do Ceara" style="height:64px;width:auto;display:block;">'
            + '</div>'
            + '<div style="border-bottom:2px solid #0f3d2e;margin:0 0 1.2em 0;"></div>';
        if (titulo) {
            html += '<p style="text-align:center;font-weight:700;font-size:14pt;color:#0f3d2e;margin:0 0 1em 0;font-family:\'Montserrat\',sans-serif;">' + titulo + '</p>';
        }
        return html;
    }

    // Bloco de identificação em duas colunas (Processo/Objeto/Analista | Versão/Conferência em)
    // usado logo abaixo de montarCabecalhoLogosRelatorio() nos relatórios de Análise Documental
    // e de Análise Técnica — todos os valores já devem vir escapados pelo chamador (mesma
    // convenção do parâmetro `titulo` acima).
    function montarIdentificacaoRelatorio(processoNup, objeto, analista, versao, conferenciaEm) {
        // Cada linha da coluna esquerda é seu próprio flex row (rótulo + valor): assim,
        // quando o valor quebra em mais de uma linha (ex.: "Objeto" longo), a quebra fica
        // recuada sob o início do próprio texto — não solta de volta pra margem esquerda,
        // por baixo do rótulo, como acontecia quando rótulo+valor eram só texto corrido.
        function linha(rotulo, valor, spanFull) {
            return '<div style="display:flex;gap:4px;' + (spanFull ? 'grid-column:1 / -1;' : '') + '">'
                + '<b style="color:#0f3d2e;white-space:nowrap;flex-shrink:0;">' + rotulo + '</b>'
                // flex:1 + min-width:0 força o valor a ocupar todo o espaço restante da
                // linha (em vez de encolher pro próprio tamanho do texto), então ele só
                // quebra quando realmente não cabe mais nenhuma palavra até a borda direita.
                + '<span style="flex:1;min-width:0;">' + (valor || '—') + '</span>'
                + '</div>';
        }
        // Grid (não flex) no nível externo de propósito: garante que "Analista" e
        // "Conferência em" fiquem sempre na mesma linha visual (última linha do grid),
        // não importa quantas linhas "Objeto" ocupe na linha do meio. A linha do Objeto
        // usa grid-column:1/-1 (ocupa as 2 colunas) — sem isso, a coluna da direita
        // (largura "auto", travada por "Conferência em: ...") reserva espaço nessa linha
        // mesmo com a célula direita vazia, sobrando como espaço em branco não usável
        // em vez de ficar disponível pro texto do Objeto quebrar só no fim da linha.
        return '<div style="display:grid;grid-template-columns:1fr auto;column-gap:18px;font-size:10pt;line-height:1.8;margin:0 0 14px 0;font-family:\'Montserrat\',sans-serif;">'
            + linha('Processo (NUP):', processoNup)
            + '<div style="text-align:right;white-space:nowrap;"><b style="color:#0f3d2e;">Versão:</b> ' + (versao || '—') + '</div>'
            + linha('Objeto:', objeto, true)
            + linha('Analista:', analista)
            + '<div style="text-align:right;white-space:nowrap;"><b style="color:#0f3d2e;">Conferência em:</b> ' + (conferenciaEm || '—') + '</div>'
            + '</div>';
    }

    function mascaraProcesso(val) {
        val = val.replace(/\D/g, '');
        val = val.replace(/^(\d{5})(\d)/, '$1.$2');
        val = val.replace(/^(\d{5})\.(\d{6})(\d)/, '$1.$2/$3');
        val = val.replace(/^(\d{5})\.(\d{6})\/(\d{4})(\d)/, '$1.$2/$3-$4');
        if (val.length > 20) val = val.substring(0, 20);
        return val;
    }

    function sanitizarNomeArquivo(nomeArquivo) {
        let nome = nomeArquivo.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        nome = nome.replace(/\s+/g, '_');
        nome = nome.replace(/[^a-zA-Z0-9._-]/g, '');
        return nome;
    }

    function extrairPathDoStorage(url) {
        if (!url) return null;
        try {
            const urlObj = new URL(url);
            const path = urlObj.pathname.replace('/storage/v1/object/public/', '');
            return path;
        } catch (e) {
            console.error('Erro ao extrair path:', e);
            return null;
        }
    }

    function dataParaISO(strData) {
        if (!strData) return null;
        if (strData.match(/^\d{4}-\d{2}-\d{2}$/)) return strData;
        const partes = strData.split('/');
        if (partes.length === 3) return `${partes[2]}-${partes[1]}-${partes[0]}`;
        return null;
    }

    function moedaParaNumero(strValor) {
        if (!strValor && strValor !== 0) return 0;
        if (typeof strValor === 'number') {
            return isFinite(strValor) ? strValor : 0;
        }
        let limpo = strValor.toString().trim().replace(/R\$|\s+/g, '');
        if (!limpo) return 0;
        if (limpo.includes(',')) {
            limpo = limpo.replace(/\./g, '').replace(',', '.');
        }
        const resultado = parseFloat(limpo);
        return isFinite(resultado) ? resultado : 0;
    }

    function isoParaDate(isoStr) {
        if (!isoStr) return null;
        if (isoStr instanceof Date) return isNaN(isoStr.getTime()) ? null : isoStr;
        if (typeof isoStr !== 'string') {
            const d = new Date(isoStr);
            return isNaN(d.getTime()) ? null : d;
        }
        // Força o horário local para evitar problemas de fuso horário (UTC vs Local)
        const d = isoStr.includes('T') ? new Date(isoStr) : new Date(isoStr + "T00:00:00");
        return isNaN(d.getTime()) ? null : d;
    }

    function getFeriados(ano) {
        const feriados = [
            "01-01",
            "04-21",
            "05-01",
            "09-07",
            "10-12",
            "11-02",
            "11-15",
            "11-20",
            "12-25",
            "03-19",
            "03-25",
            "02-17",
            "02-18",
            "06-04",
            "10-28",
        ];
        return feriados.map(f => `${ano}-${f}`);
    }

    function obterProximoDiaUtil(data) {
        let d = new Date(data);
        let tentativa = 0;
        while (tentativa < 15) {
            const diaSemana = d.getDay();
            const dataFormatada = d.toISOString().substring(5, 10);
            const feriados = getFeriados(d.getFullYear());
            const ehFeriado = feriados.some(f => f.endsWith(dataFormatada));

            if (diaSemana === 0 || diaSemana === 6 || ehFeriado) {
                d.setDate(d.getDate() + 1);
            } else {
                return d;
            }
            tentativa++;
        }
        return d;
    }

    function somarDiasUteis(data, dias) {
        let d = new Date(data);
        let cont = 0;
        let seguranca = 0;
        while (cont < dias && seguranca < 100) {
            d.setDate(d.getDate() + 1);
            const diaSemana = d.getDay();
            const dataFormatada = d.toISOString().substring(5, 10);
            const feriados = getFeriados(d.getFullYear());
            const ehFeriado = feriados.some(f => f.endsWith(dataFormatada));

            if (diaSemana !== 0 && diaSemana !== 6 && !ehFeriado) {
                cont++;
            }
            seguranca++;
        }
        return d;
    }

    function calcularDataMeta(dataBase, diasParaSoma = 20) {
        if (!dataBase) return null;
        let data = (dataBase instanceof Date) ? new Date(dataBase) : new Date(dataBase);

        // Inicia a contagem no próximo dia útil após a dataBase
        let amanha = new Date(data);
        amanha.setDate(amanha.getDate() + 1);
        let dataInicioContagem = obterProximoDiaUtil(amanha);

        // Soma exatamente 'diasParaSoma' dias úteis começando em dataInicioContagem
        // Como 'somarDiasUteis' avança a partir da data fornecida, para contar
        // dataInicioContagem como dia 1, somamos (diasParaSoma - 1)
        const diasASomar = Math.max(0, diasParaSoma - 1);
        return somarDiasUteis(dataInicioContagem, diasASomar);
    }

    function dateParaInput(dateObj) {
        if (!dateObj || !(dateObj instanceof Date) || isNaN(dateObj)) return "";
        return dateObj.toLocaleDateString('pt-BR');
    }

    function formatCompact(num) {
        if (num === null || num === undefined) return 'R$ 0,00';
        return num.toLocaleString('pt-BR', { style: 'currency', currency: 'BRL', minimumFractionDigits: 2, maximumFractionDigits: 2 });
    }

    function formatPercentage(num) {
        if (num === null || num === undefined || !isFinite(num)) return '';
        return num.toFixed(1).replace('.', ',') + '%';
    }

    function isFiniteNumber(v) { return typeof v === 'number' && isFinite(v); }

    function escapeHTML(str) { const s = String(str || ''); return s.replace(/[&<>"']/g, function (m) { return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[m]; }); }

    /* Sanitiza HTML rico salvo pelo editor contentEditable do comentário da Curva ABC
       (negrito/itálico/sublinhado/alinhamento/recuo/tamanho de fonte, via execCommand).
       Diferente de escapeHTML() — aqui o objetivo é MANTER a formatação, só removendo
       o que pode executar JS (script, on*, javascript:, etc.). Usa DOMPurify (carregado
       via CDN em index.html); se por algum motivo a lib não carregar, cai para
       escapeHTML() puro (perde formatação, mas nunca executa HTML não confiável). */
    function sanitizeRichHTML(html) {
        if (typeof DOMPurify === 'undefined') return escapeHTML(html);
        return DOMPurify.sanitize(String(html || ''), {
            ALLOWED_TAGS: ['b', 'strong', 'i', 'em', 'u', 'font', 'span', 'div', 'p', 'br', 'ul', 'ol', 'li'],
            ALLOWED_ATTR: ['style']
        });
    }

    function sum(rows, fn) { return rows.reduce((acc, it) => { const v = fn(it); return acc + (isFiniteNumber(v) ? v : 0); }, 0); }

    function formatStatusDisplay(status) {
        if (status === "DEVOLVIDO P/ REANÁLISE FISCAL") return "REANÁLISE FISCAL";
        return status;
    }

    function parseMoneyInput(val) {
        if (val === null || val === undefined || val === '') return 0;
        let s = val.toString().trim();
        s = s.replace(/[\u2212\u2013\u2014]/g, '-');
        if (/^\(.*\)$/.test(s)) { s = '-' + s.replace(/^\(|\)$/g, ''); }
        s = s.replace(/R\$|\s|\u00A0/g, '');
        s = s.replace(/[^0-9\-,.]/g, '');
        if (!s || s === '-') return 0;
        if (s.includes(',')) {
            s = s.replace(/\./g, '').replace(',', '.');
        } else if (s.split('.').length > 2) {
            s = s.replace(/\./g, '');
        }
        const res = parseFloat(s);
        return isFinite(res) ? res : 0;
    }

    function formatCurrencyValue(val) { return val.toLocaleString('pt-BR', { minimumFractionDigits: 2 }); }

    function debounce(func, wait) {
        let timeout;
        return function (...args) {
            const context = this;
            clearTimeout(timeout);
            timeout = setTimeout(() => func.apply(context, args), wait);
        };
    }

    // Expor no escopo global (conforme diretriz: anexar ao objeto window)
    window.montarCabecalhoLogosRelatorio = montarCabecalhoLogosRelatorio;
    window.montarIdentificacaoRelatorio = montarIdentificacaoRelatorio;
    window.mascaraProcesso = mascaraProcesso;
    window.sanitizarNomeArquivo = sanitizarNomeArquivo;
    window.extrairPathDoStorage = extrairPathDoStorage;
    window.dataParaISO = dataParaISO;
    window.moedaParaNumero = moedaParaNumero;
    window.isoParaDate = isoParaDate;
    window.getFeriados = getFeriados;
    window.obterProximoDiaUtil = obterProximoDiaUtil;
    window.somarDiasUteis = somarDiasUteis;
    window.calcularDataMeta = calcularDataMeta;
    window.dateParaInput = dateParaInput;
    window.formatCompact = formatCompact;
    window.formatPercentage = formatPercentage;
    window.isFiniteNumber = isFiniteNumber;
    window.escapeHTML = escapeHTML;
    window.sanitizeRichHTML = sanitizeRichHTML;
    window.sum = sum;
    window.formatStatusDisplay = formatStatusDisplay;
    window.parseMoneyInput = parseMoneyInput;
    window.formatCurrencyValue = formatCurrencyValue;
    window.debounce = debounce;

})(window);
